import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.resolve(process.cwd(), "tasks.db");

let db: Database.Database;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    initSchema(db);
  }
  return db;
}

function initSchema(db: Database.Database) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      command TEXT NOT NULL,
      interval_seconds INTEGER NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('ACTIVE', 'PAUSED'))
    );

    CREATE TABLE IF NOT EXISTS execution_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('SUCCESS', 'FAILED')),
      timestamp TEXT NOT NULL
    );
  `);
}

export interface Task {
  id: string;
  name: string;
  command: string;
  interval_seconds: number;
  status: "ACTIVE" | "PAUSED";
}

export interface ExecutionHistory {
  id: number;
  task_id: string;
  status: "SUCCESS" | "FAILED";
  timestamp: string;
}

export function getAllTasks(): Task[] {
  return getDb().prepare("SELECT * FROM tasks").all() as Task[];
}

export function getTaskById(id: string): Task | undefined {
  return getDb().prepare("SELECT * FROM tasks WHERE id = ?").get(id) as
    | Task
    | undefined;
}

export function createTask(task: Task): Task {
  getDb()
    .prepare(
      "INSERT INTO tasks (id, name, command, interval_seconds, status) VALUES (?, ?, ?, ?, ?)"
    )
    .run(
      task.id,
      task.name,
      task.command,
      task.interval_seconds,
      task.status
    );
  return task;
}

export function updateTaskStatus(
  id: string,
  status: "ACTIVE" | "PAUSED"
): boolean {
  const result = getDb()
    .prepare("UPDATE tasks SET status = ? WHERE id = ?")
    .run(status, id);
  return result.changes > 0;
}

export function addExecutionHistory(
  taskId: string,
  status: "SUCCESS" | "FAILED",
  timestamp: string
): void {
  getDb()
    .prepare(
      "INSERT INTO execution_history (task_id, status, timestamp) VALUES (?, ?, ?)"
    )
    .run(taskId, status, timestamp);
}

export function getExecutionHistory(taskId: string): ExecutionHistory[] {
  return getDb()
    .prepare(
      "SELECT * FROM execution_history WHERE task_id = ? ORDER BY timestamp DESC"
    )
    .all(taskId) as ExecutionHistory[];
}

export function getAllExecutionHistory(): ExecutionHistory[] {
  return getDb()
    .prepare("SELECT * FROM execution_history ORDER BY timestamp DESC")
    .all() as ExecutionHistory[];
}

import { exec } from "child_process";
import { getAllTasks, addExecutionHistory, getDb } from "./db";

let runnerInterval: ReturnType<typeof setInterval> | null = null;
// Track last execution time per task to respect interval_seconds
const lastExecutionTime: Map<string, number> = new Map();

export function startRunner(): void {
  if (runnerInterval) return;

  // Poll every second to check for tasks that need execution
  runnerInterval = setInterval(() => {
    try {
      const tasks = getAllTasks();
      const now = Date.now();

      for (const task of tasks) {
        if (task.status !== "ACTIVE") continue;

        const lastTime = lastExecutionTime.get(task.id) || 0;
        const intervalMs = task.interval_seconds * 1000;

        if (now - lastTime >= intervalMs) {
          lastExecutionTime.set(task.id, now);
          executeTask(task.id, task.command);
        }
      }
    } catch (err) {
      console.error("Runner error:", err);
    }
  }, 1000);

  console.log("[Runner] Background task runner started");
}

export function stopRunner(): void {
  if (runnerInterval) {
    clearInterval(runnerInterval);
    runnerInterval = null;
    console.log("[Runner] Background task runner stopped");
  }
}

export function executeTask(taskId: string, command: string): void {
  exec(command, { timeout: 30000 }, (error, stdout, stderr) => {
    const status = error ? ("FAILED" as const) : ("SUCCESS" as const);
    const timestamp = new Date().toISOString();

    if (stdout) console.log(`[Task ${taskId}] stdout:`, stdout.trim());
    if (stderr) console.error(`[Task ${taskId}] stderr:`, stderr.trim());

    try {
      addExecutionHistory(taskId, status, timestamp);
      console.log(`[Task ${taskId}] Executed: ${status} at ${timestamp}`);
    } catch (err) {
      console.error(`[Task ${taskId}] Failed to log execution:`, err);
    }
  });
}

export function triggerTask(taskId: string, command: string): void {
  executeTask(taskId, command);
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getAllTasks, createTask } from "../../../db";
import { startRunner } from "../../../runner";

export const onGet: RequestHandler = async ({ json }) => {
  const tasks = getAllTasks();
  json(200, tasks);
};

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const body = await request.json();

    // Validate required fields
    if (!body.id || typeof body.id !== "string") {
      json(400, { error: "Field 'id' is required and must be a string" });
      return;
    }
    if (!body.name || typeof body.name !== "string") {
      json(400, { error: "Field 'name' is required and must be a string" });
      return;
    }
    if (!body.command || typeof body.command !== "string") {
      json(400, { error: "Field 'command' is required and must be a string" });
      return;
    }
    if (
      !body.interval_seconds ||
      typeof body.interval_seconds !== "number" ||
      body.interval_seconds <= 0 ||
      !Number.isInteger(body.interval_seconds)
    ) {
      json(400, {
        error:
          "Field 'interval_seconds' is required and must be a positive integer",
      });
      return;
    }
    if (
      !body.status ||
      (body.status !== "ACTIVE" && body.status !== "PAUSED")
    ) {
      json(400, {
        error: "Field 'status' must be either 'ACTIVE' or 'PAUSED'",
      });
      return;
    }

    const task = {
      id: body.id,
      name: body.name,
      command: body.command,
      interval_seconds: body.interval_seconds,
      status: body.status,
    };

    createTask(task);
    json(201, task);
  } catch (e) {
    json(400, { error: "Invalid JSON body" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getTaskById, updateTaskStatus } from "../../../../../db";

export const onPost: RequestHandler = async ({ params, json }) => {
  const id = params.id;
  const task = getTaskById(id);

  if (!task) {
    json(404, { error: "Task not found" });
    return;
  }

  updateTaskStatus(id, "PAUSED");
  json(200, { id, status: "PAUSED" });
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getTaskById, updateTaskStatus } from "../../../../../db";

export const onPost: RequestHandler = async ({ params, json }) => {
  const id = params.id;
  const task = getTaskById(id);

  if (!task) {
    json(404, { error: "Task not found" });
    return;
  }

  updateTaskStatus(id, "ACTIVE");
